script:
html { scroll-behavior: smooth; }
::selection { background: var(--c9e52d84-7a16-4b39-8f02-5d3c1e7a9006, #2E45E6); color: #FFFFFF; }
body { -webkit-font-smoothing: antialiased; }

/* the ring is a conic gradient with a punched centre */
.pl-ring { background: conic-gradient(var(--c9e52d84-7a16-4b39-8f02-5d3c1e7a9006, #2E45E6) 0 72%, var(--c9e52d84-7a16-4b39-8f02-5d3c1e7a9005, #E8E8E5) 72% 100%); }

/* quiet interactions */
.pl-link { transition: color 0.18s ease; }
.pl-link:hover { color: var(--c9e52d84-7a16-4b39-8f02-5d3c1e7a9006, #2E45E6); }
.pl-btn { transition: transform 0.18s ease, opacity 0.18s ease; }
.pl-btn:hover { opacity: 0.9; transform: translateY(-1px); }

a:focus-visible { border-radius: 6px; outline: 2px solid var(--c9e52d84-7a16-4b39-8f02-5d3c1e7a9006, #2E45E6); outline-offset: 3px; }
